beforeSaveCustomScript:
if (
    status == 'Completed'
    && entity\isAttributeChanged('status')
    && parentType == 'CIncident'
    && name == 'TASK FALSO POSITIVO TEST'
) {

    $actions = record\attribute(parentType, parentId, 'actionsTaken');

    if (array\includes($actions, 'Sospecha de falso positivo')) {

        $index = array\indexOf($actions, 'Sospecha de falso positivo');
        $actions = array\removeAt($actions, $index);

    }

    $actions = array\push($actions, 'Falso positivo');

    record\update(
        parentType,
        parentId,
        'status', 'Resuelto',
        'actionsTaken', $actions
    );

}
